INSERT INTO `locales_spell` (`entry`, `description_loc4`) VALUES (50039, '禁止与玩家交易和使用拍卖行。\n\n限制与其他玩家组队。 \n\n无法制作装备。\n\n不能使用治疗药水以外的消耗品。\n\n死后自动在墓地复活。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
INSERT INTO `locales_spell` (`entry`, `description_loc4`) VALUES (50040, '你将无法关闭战争模式，击杀玩家即可获得经验值，并在开放世界、战场和竞技场中获得额外经验值。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
