INSERT INTO `locales_spell` (`entry`, `description_loc4`) VALUES (50043, '你不是东西，无才才德，根本就不该出生。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
INSERT INTO `locales_spell` (`entry`, `description_loc4`) VALUES (50044, '时间就是金钱，朋友！\n\n-无法与其他玩家交易或接收来自其他玩家的邮件。\n\n-卖给商贩的物品没有价值。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
